    return { failed: true, comment: ctx.noTicket ? null : buildDetailsFailureComment(ctx.ticketKey, pr.number) };
}

// Step 4: checkout the PR branch (non-fatal on failure)
function checkoutPrBranch(ctx, branchName) {
    try {
        if (branchName) {
