function prTrackerGlobals(record, trackerThrows) {
    var g = {
        jira_post_comment: function(a) { record.comments.push({ tool: 'jira_post_comment', args: a }); },
        jira_add_label: function(a) { record.comments.push({ tool: 'jira_add_label', args: a }); },
