            ' | head=' + (prDetails.head && prDetails.head.ref ? prDetails.head.ref : '(missing)') +
            ' | base=' + (prDetails.base && prDetails.base.ref ? prDetails.base.ref : '(missing)') +
            ' | changed_files=' + (prDetails.changed_files || 0));

